:root {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: #0b0f19;
  color: #f3f4f6;
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

*, *::before, *::after {
  box-sizing: inherit;
}

body {
  margin: 0;
  padding: 0;
  overflow: hidden;
  width: 100vw;
  height: 100vh;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background: radial-gradient(circle at center, #111827 0%, #030712 100%);
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.particle-canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.controls-panel {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 10;
  background: rgba(17, 24, 39, 0.75);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  padding: 20px;
  width: 300px;
  max-height: calc(100vh - 40px);
  overflow-y: auto;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 10px 10px -5px rgba(0, 0, 0, 0.4);
  transition: transform 0.3s ease, opacity 0.3s ease;
}

.control-group {
  margin-bottom: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.control-group:last-child {
  margin-bottom: 0;
}

.control-group label {
  font-size: 0.85rem;
  font-weight: 500;
  color: #9ca3af;
  display: flex;
  justify-content: space-between;
}

.control-group input[type="range"] {
  width: 100%;
  accent-color: #3b82f6;
  cursor: pointer;
}

.control-group select,
.control-group input[type="color"] {
  width: 100%;
  padding: 8px;
  background: rgba(31, 41, 55, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  color: #fff;
  font-size: 0.9rem;
  outline: none;
  cursor: pointer;
}

.control-group input[type="color"] {
  height: 40px;
  padding: 2px;
}

.btn {
  background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
  color: white;
  border: none;
  border-radius: 8px;
  padding: 10px 16px;
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 6px -1px rgba(59, 130, 246, 0.3);
  text-align: center;
}

.btn:hover {
  background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%);
  box-shadow: 0 6px 8px -1px rgba(59, 130, 246, 0.4);
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
}

.title {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0 0 16px 0;
  color: #f9fafb;
  letter-spacing: -0.025em;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding-bottom: 10px;
}

.instruction {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  background: rgba(17, 24, 39, 0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  padding: 10px 20px;
  border-radius: 30px;
  font-size: 0.85rem;
  color: #9ca3af;
  pointer-events: none;
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3);
  animation: pulse-instruction 3s infinite ease-in-out;
}

@keyframes pulse-instruction {
  0%, 100% { opacity: 0.7; }
  50% { opacity: 1; }
}

@media (max-width: 640px) {
  .controls-panel {
    top: auto;
    bottom: 20px;
    right: 10px;
    left: 10px;
    width: auto;
    max-height: 45vh;
  }

  .instruction {
    display: none;
  }
}

import { useEffect, useRef, useState } from 'react';

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  color: string;
  alpha: number;
  life: number;
  maxLife: number;
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  // コントロール状態
  const [particleCount, setParticleCount] = useState<number>(50);
  const [particleColor, setParticleColor] = useState<string>('#3b82f6');
  const [particleSize, setParticleSize] = useState<number>(4);
  const [speed, setSpeed] = useState<number>(2);
  const [shape, setShape] = useState<'circle' | 'square' | 'star'>('circle');
  const [trailEffect, setTrailEffect] = useState<boolean>(true);

  // マウス/タッチ位置管理
  const pointerRef = useRef<{ x: number; y: number; active: boolean }>({
    x: 0,
    y: 0,
    active: false,
  });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    const handleResize = () => {
      if (!canvas) return;
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
    };

    window.addEventListener('resize', handleResize);

    const particles: Particle[] = [];

    // 初期マウス位置を画面中心に設定
    pointerRef.current.x = width / 2;
    pointerRef.current.y = height / 2;

    const handleMouseMove = (e: MouseEvent) => {
      pointerRef.current.x = e.clientX;
      pointerRef.current.y = e.clientY;
      pointerRef.current.active = true;
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        pointerRef.current.x = e.touches[0].clientX;
        pointerRef.current.y = e.touches[0].clientY;
        pointerRef.current.active = true;
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('touchmove', handleTouchMove);
    window.addEventListener('touchstart', handleTouchMove);

    // パーティクル生成ヘルパー
    const createParticle = (x: number, y: number): Particle => {
      const angle = Math.random() * Math.PI * 2;
      const s = (Math.random() * 2 + 1) * (speed * 0.5);
      return {
        x,
        y,
        vx: Math.cos(angle) * s,
        vy: Math.sin(angle) * s,
        size: Math.random() * particleSize + 2,
        color: particleColor,
        alpha: 1,
        life: 0,
        maxLife: Math.random() * 60 + 40,
      };
    };

    // メインアニメーションループ
    const render = () => {
      if (trailEffect) {
        ctx.fillStyle = 'rgba(3, 7, 18, 0.2)';
        ctx.fillRect(0, 0, width, height);
      } else {
        ctx.clearRect(0, 0, width, height);
      }

      // ターゲット位置に向かってパーティクルを追加
      if (pointerRef.current.active) {
        for (let i = 0; i < particleCount / 10; i++) {
          particles.push(
            createParticle(
              pointerRef.current.x + (Math.random() - 0.5) * 20,
              pointerRef.current.y + (Math.random() - 0.5) * 20
            )
          );
        }
      }

      // パーティクルの更新と描画
      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life++;
        p.alpha = 1 - p.life / p.maxLife;

        if (p.life >= p.maxLife || p.alpha <= 0) {
          particles.splice(i, 1);
          continue;
        }

        ctx.save();
        ctx.globalAlpha = Math.max(0, p.alpha);
        ctx.fillStyle = p.color;
        ctx.strokeStyle = p.color;

        if (shape === 'circle') {
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          ctx.fill();
        } else if (shape === 'square') {
          ctx.fillRect(p.x - p.size, p.y - p.size, p.size * 2, p.size * 2);
        } else if (shape === 'star') {
          // 簡単な星型
          ctx.beginPath();
          const spikes = 5;
          const outerRadius = p.size * 1.5;
          const innerRadius = p.size * 0.7;
          let rot = (Math.PI / 2) * 3;
          let cx = p.x;
          let cy = p.y;
          let step = Math.PI / spikes;

          ctx.moveTo(cx, cy - outerRadius);
          for (let s = 0; s < spikes; s++) {
            cx = p.x + Math.cos(rot) * outerRadius;
            cy = p.y + Math.sin(rot) * outerRadius;
            ctx.lineTo(cx, cy);
            rot += step;

            cx = p.x + Math.cos(rot) * innerRadius;
            cy = p.y + Math.sin(rot) * innerRadius;
            ctx.lineTo(cx, cy);
            rot += step;
          }
          ctx.lineTo(p.x, p.y - outerRadius);
          ctx.closePath();
          ctx.fill();
        }

        ctx.restore();
      }

      // 最大パーティクル数の制限
      if (particles.length > 1000) {
        particles.splice(0, particles.length - 1000);
      }

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchstart', handleTouchMove);
      cancelAnimationFrame(animationFrameId);
    };
  }, [particleCount, particleColor, particleSize, speed, shape, trailEffect]);

  const handleReset = () => {
    setParticleCount(50);
    setParticleColor('#3b82f6');
    setParticleSize(4);
    setSpeed(2);
    setShape('circle');
    setTrailEffect(true);
  };

  return (
    <div className="app-container">
      <div className="canvas-container">
        <canvas ref={canvasRef} className="particle-canvas" />
      </div>

      <div className="controls-panel">
        <h2 className="title">パーティクル設定</h2>

        <div className="control-group">
          <label>
            <span>発生量</span>
            <span>{particleCount}</span>
          </label>
          <input
            type="range"
            min="10"
            max="200"
            value={particleCount}
            onChange={(e) => setParticleCount(Number(e.target.value))}
          />
        </div>

        <div className="control-group">
          <label>
            <span>速度</span>
            <span>{speed}</span>
          </label>
          <input
            type="range"
            min="0.5"
            max="5"
            step="0.5"
            value={speed}
            onChange={(e) => setSpeed(Number(e.target.value))}
          />
        </div>

        <div className="control-group">
          <label>
            <span>サイズ</span>
            <span>{particleSize}</span>
          </label>
          <input
            type="range"
            min="1"
            max="10"
            value={particleSize}
            onChange={(e) => setParticleSize(Number(e.target.value))}
          />
        </div>

        <div className="control-group">
          <label>カラー</label>
          <input
            type="color"
            value={particleColor}
            onChange={(e) => setParticleColor(e.target.value)}
          />
        </div>

        <div className="control-group">
          <label>形状</label>
          <select
            value={shape}
            onChange={(e) => setShape(e.target.value as 'circle' | 'square' | 'star')}
          >
            <option value="circle">サークル</option>
            <option value="square">スクエア</option>
            <option value="star">スター</option>
          </select>
        </div>

        <div className="control-group">
          <label>
            <span>軌跡エフェクト</span>
            <input
              type="checkbox"
              checked={trailEffect}
              onChange={(e) => setTrailEffect(e.target.checked)}
            />
          </label>
        </div>

        <div className="control-group" style={{ marginTop: '12px' }}>
          <button className="btn" onClick={handleReset}>
            設定リセット
          </button>
        </div>
      </div>

      <div className="instruction">
        画面上でマウスまたは指を動かしてパーティクルを発生させよう
      </div>
    </div>
  );
}
